 if(mode==='pilot'){
  box.replaceChildren(elem('h3','','Text handling · pilot narratives'),elem('p','','Text handling is fixed for the original 48-narrative pilot, so the selector is disabled. Similarity uses the original evidence-oriented text processing.'));
  return;
 }
