/* Compact, view-specific presentation of existing graph quantities. */
function installGuidedCards(){
 const summary=$('networkSummary'),reading=elem('section','color-description reading-guide');reading.id='readingGuide';reading.setAttribute('aria-label','How to read this view');
 const heading=elem('h3','','How to read this view'),connections=elem('p'),colors=elem('p'),details=elem('details','reading-methods');connections.id='readConnections';colors.id='readColors';details.id='readingMethods';details.append(elem('summary','','Methods and limitations'));
 const math=elem('p');math.id='connectionMath';
 summary.before(reading);reading.append(heading,connections,colors,$('textHandlingDescription'),details);details.append($('connectionDescription'),math,$('colorDescription'));
 // Put findings immediately after the map, followed by the compact reading guide.
 reading.before(summary);
}
function readingLine(id,label,text){const p=$(id);p.replaceChildren(elem('strong','',label+' '),document.createTextNode(text));}
function renderReadingGuide(){
 const pilot=mode==='pilot',unit=$('edgeUnit').value,layer=$('colorLayer').value;
 const connection=pilot?'Lines link pilot narratives with similar phrase patterns.':unit==='hospice'?'Lines link phrases mentioned by the same hospices, possibly in different surveys.':unit==='record'?'Lines link phrases with similar frequency-and-rarity patterns across text entries (TF-IDF cosine).':unit==='severity'?'Lines link phrases appearing together above a baseline, giving more weight to entries with higher provisional severity scores.':'Lines link phrases appearing together more than their separate frequencies would predict.';
 readingLine('readConnections','Connections.',connection+' '+(pilot?'Nodes represent individual reading cases.':'Node size counts distinct identified hospices with matching wording.'));
 let color;
 if(pilot)color=layer==='severity'?'Colors show each narrative’s provisional severity band; no match does not establish no harm.':layer==='ij'?'Colors show the source IJ status of each selected narrative.':layer==='none'?'All nodes use a neutral color.':'Colors identify surveying organizations.';
 else if(layer==='community')color='Colors group phrases by their displayed connections. These are exploratory wording clusters, not severity grades or validated themes.';
 else if(layer==='severity')color='Colors show the share of matching hospices with at least one High-scored entry (provisional score ≥ 2); the score can come from another passage in that entry.';
 else if(layer==='ij')color='Colors show matching hospices with a source Immediate Jeopardy (IJ) flag, among matching hospices with a known flag.';
 else if(layer==='condition')color='Colors show the share of matching hospices with a condition-level source classification, separate from our severity score.';
 else if(layer==='legacyCommunity')color='Colors retain the original record-network communities; they are not fitted to these displayed connections.';
 else color='All nodes use a neutral color with no analytical meaning.';
 if(!pilot&&$('severityTerms').checked)color+=' Diamonds identify predefined severity families; they can share a group with ordinary care phrases.';
 if(isSourceComparison())color+=' Groups are fitted separately; matching hues do not establish matching groups. Both selections use the same positions and size scale.';
 readingLine('readColors',pilot?'Colors.':'Colors and shapes.',color);
 const math=$('connectionMath');
 if(!pilot&&isPPMI())math.textContent='Connection math: PPMI = max(0, log₂(lift)); lift = joint share ÷ (first phrase share × second phrase share). '+(unit==='severity'?'Shares use record weights of 1 + provisional record score.':'Each record has equal weight.')+` The current minimum lift is ${Math.pow(2,Number($('threshold').value)).toFixed(3)}. Shared-record support is unweighted: at least ${$('shared').value} records for phrase pairs${$('severityTerms').checked?' and 10 for severity-family links':''}. After these cutoffs, retain a link if it is among either endpoint’s ${$('neighbors').value} strongest candidates. This is not a significance test.`;
 else math.textContent='Connection math: cosine = dot product of the two feature vectors ÷ the product of their lengths. '+(unit==='hospice'&&!pilot?'Vectors indicate phrase presence at each identified hospice.':'Vectors use phrase-frequency and inverse-document-frequency weights.')+' The selected thresholds and strongest-neighbor limit determine which connections appear.';
 // Keep a single disclosure; the existing policy details remain fully available inside it.
 for(const nested of [...$('connectionDescription').querySelectorAll('details')])nested.replaceWith(...[...nested.children].filter(e=>e.tagName!=='SUMMARY'));
}
function summaryCoverage(n,g){return `${count(n?.hospice?.count||0)} (${summaryPercentage(n?.hospice?.count||0,g.hospiceTotals.count)})`;}
function summaryPairs(grid,edges,g,pilot,unit,comparison){
 if(!edges.length)return;
 const pairs=summaryTable('Top 3 strongest pairs'+(comparison?' · active selection':''),['Pair',pilot?'':unit==='hospice'?'Shared hospices':'Shared text entries',!pilot&&isPPMI()?'Lift':'Cosine']);pairs.wrap.classList.add('summary-pairs');
 for(const e of edges.slice(0,3)){
  const row=elem('tr'),pair=elem('td');row.dataset.source=e.source;row.dataset.target=e.target;pair.append(summaryPhrase(g.nodes.find(n=>n.id===e.source)),document.createTextNode(' ↔ '),summaryPhrase(g.nodes.find(n=>n.id===e.target)));
  row.append(pair,elem('td','',pilot?'—':count(e.shared)),elem('td','',!pilot&&isPPMI()?e.lift.toFixed(2)+'×':e.weight.toFixed(3)));pairs.tbody.append(row);
 }grid.append(pairs.wrap);
}
