 const g=displayedGraph,nodes=shownNodes,edges=[...shownEdges].sort((a,b)=>b.weight-a.weight||(b.shared||0)-(a.shared||0)||String(a.source).localeCompare(String(b.source))),pilot=mode==='pilot',unit=$('edgeUnit').value,comparison=isSourceComparison(),severity=!pilot&&(guidedState.view==='severity'||comparison&&guidedState.lens==='severity');
 box.dataset.records=String(pilot?g.nodes.length:g.documents);box.dataset.nodes=String(nodes.length);box.dataset.edges=String(edges.length);box.dataset.view=pilot?'pilot':guidedState.view;
